# Sample Summary And Feature Filtering


::: {.cell}

```{.r .cell-code}
sample_summary <- metadata %>%
  tibble::rownames_to_column("sample_name") %>%
  mutate(
    library_size_raw = colSums(gene_counts)[sample_name]
